#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define MAX_FRAME_SIZE 65536
#define MAX_CLIENTS 64
#define MAX_PAYLOAD 1024
#define ROLE_GUEST 0
#define ROLE_USER 1
#define ROLE_ADMIN 2

typedef struct {
    int fd;
    uint8_t role;
    char username[32];
    uint8_t handler_id;
} client_session;

typedef struct {
    client_session clients[MAX_CLIENTS];
    int num_clients;
    char server_secret[64];
} ws_server;

static ws_server g_server;

typedef void (*msg_handler_fn)(client_session*, const char*, size_t);

void handle_admin_cmd(client_session *sess, const char *data, size_t len) {
    char response[256];
    snprintf(response, sizeof(response), "Admin command executed by %s", sess->username);
    write(sess->fd, response, strlen(response));
}

void handle_user_msg(client_session *sess, const char *data, size_t len) {
    char response[256];
    snprintf(response, sizeof(response), "Message from %s received", sess->username);
    write(sess->fd, response, strlen(response));
}

void handle_guest_ping(client_session *sess, const char *data, size_t len) {
    const char *pong = "PONG";
    write(sess->fd, pong, 4);
}

static const msg_handler_fn handler_table[] = {
    handle_guest_ping,
    handle_user_msg,
    handle_admin_cmd
};
#define NUM_HANDLERS (sizeof(handler_table)/sizeof(handler_table[0]))

static int validate_frame_header(const uint8_t *buf, size_t buflen, uint64_t *payload_len) {
    if (buflen < 2) return -1;
    uint8_t second = buf[1] & 0x7F;
    if (second <= 125) {
        *payload_len = second;
        return 2;
    } else if (second == 126) {
        if (buflen < 4) return -1;
        *payload_len = (buf[2] << 8) | buf[3];
        return 4;
    } else {
        if (buflen < 10) return -1;
        *payload_len = ((uint64_t)buf[2] << 56) | ((uint64_t)buf[3] << 48) |
                       ((uint64_t)buf[4] << 40) | ((uint64_t)buf[5] << 32) |
                       ((uint64_t)buf[6] << 24) | ((uint64_t)buf[7] << 16) |
                       ((uint64_t)buf[8] << 8)  | (uint64_t)buf[9];
        return 10;
    }
}

static int authorize_action(client_session *sess, uint8_t required_role) {
    return sess->role >= required_role;
}

static void dispatch_message(client_session *sess, uint8_t opcode,
                             const char *payload, size_t payload_len) {
    switch (opcode) {
        case 0x01: /* text frame - role check for admin */
            if (payload_len > 5 && memcmp(payload, "ADMIN:", 6) == 0) {
                if (!authorize_action(sess, ROLE_ADMIN)) {
                    const char *denied = "Access denied";
                    write(sess->fd, denied, strlen(denied));
                    return;
                }
                sess->handler_id = 2; /* ADMIN handler index */
            }
            if (sess->handler_id < NUM_HANDLERS) {
                handler_table[sess->handler_id](sess, payload, payload_len);
            }
            break;
        case 0x09: /* ping */
            handle_guest_ping(sess, payload, payload_len);
            break;
        default:
            break;
    }
}

static void process_client_frame(client_session *sess) {
    uint8_t buf[MAX_FRAME_SIZE];
    ssize_t n = read(sess->fd, buf, sizeof(buf));
    if (n <= 0) return;

    uint64_t payload_len;
    int header_size = validate_frame_header(buf, (size_t)n, &payload_len);
    if (header_size < 0) return;

    /* Validate payload length with 64-bit arithmetic to prevent overflow */
    if (payload_len > MAX_PAYLOAD) return;
    uint64_t total_needed = (uint64_t)header_size + 4 + payload_len;
    if (total_needed > (uint64_t)n) return;

    /* Unmask payload in-place using 4-byte XOR key after header */
    uint8_t mask_key[4];
    memcpy(mask_key, buf + header_size, 4);
    char *payload_start = (char*)(buf + header_size + 4);

    /* Stack buffer for unmasked payload - bounded by MAX_PAYLOAD */
    char unmasked[MAX_PAYLOAD];
    size_t copy_len = (size_t)payload_len;
    memcpy(unmasked, payload_start, copy_len);

    for (size_t i = 0; i < copy_len; i++) {
        unmasked[i] ^= mask_key[i % 4];
    }

    uint8_t opcode = buf[0] & 0x0F;
    dispatch_message(sess, opcode, unmasked, copy_len);
}

static client_session* accept_client(int server_fd) {
    struct sockaddr_in addr;
    socklen_t addrlen = sizeof(addr);
    int client_fd = accept(server_fd, (struct sockaddr*)&addr, &addrlen);
    if (client_fd < 0) return NULL;

    if (g_server.num_clients >= MAX_CLIENTS) {
        close(client_fd);
        return NULL;
    }

    client_session *sess = &g_server.clients[g_server.num_clients++];
    sess->fd = client_fd;
    sess->role = ROLE_GUEST;
    strncpy(sess->username, "anonymous", sizeof(sess->username) - 1);
    sess->username[sizeof(sess->username) - 1] = '\0';
    sess->handler_id = 0;
    return sess;
}

int main(int argc, char *argv[]) {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr = {.sin_family = AF_INET, .sin_port = htons(8080),
                               .sin_addr.s_addr = INADDR_ANY};
    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 10);

    memset(&g_server, 0, sizeof(g_server));

    /* Load the server secret from the environment instead of hardcoding it (CWE-798 fix). */
    const char *secret_env = getenv("WS_SERVER_SECRET");
    if (secret_env == NULL || secret_env[0] == '\0') {
        fprintf(stderr, "Error: WS_SERVER_SECRET environment variable must be set.\n");
        close(server_fd);
        return 1;
    }
    strncpy(g_server.server_secret, secret_env, sizeof(g_server.server_secret) - 1);
    g_server.server_secret[sizeof(g_server.server_secret) - 1] = '\0';

    while (1) {
        client_session *sess = accept_client(server_fd);
        if (sess) {
            process_client_frame(sess);
        }
    }
    return 0;
}
